return ['domain'=>'mlab-core','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'MomentumLab Core 0.5.0','pot-creation-date'=>'2026-11-10 10:23+0000','po-revision-date'=>'2026-11-10 10:25+0000','messages'=>['MomentumLab Core'=>'MomentumLab Core','Shows the MomentumLab plugins with your license key, installs and activates them with one click, and keeps them up to date. Manages the GitHub read tokens for updates from private repositories.'=>'Affiche les extensions MomentumLab avec votre clé de licence, les installe et les active en un clic, et les maintient à jour. Gère les jetons de lecture GitHub pour les mises à jour des dépôts privés.','MomentumLab'=>'MomentumLab','https://momentumlab.ch'=>'https://momentumlab.ch','You are not allowed to do this. Ask an administrator.'=>'Vous n’avez pas l’autorisation de faire cela. Demandez à un administrateur.','This plugin is not in the list. Press "Reload list" and try again.'=>'Cette extension ne figure pas dans la liste. Cliquez sur « Recharger la liste » et réessayez.','The list is up to date.'=>'La liste est à jour.','This plugin is not part of your license. Please contact MomentumLab.'=>'Cette extension ne fait pas partie de votre licence. Veuillez contacter MomentumLab.','The plugin is installed and active.'=>'L’extension est installée et active.','The plugin is not installed. Switch it on to install it.'=>'L’extension n’est pas installée. Activez-la pour l’installer.','The plugin is active.'=>'L’extension est active.','The plugin is switched off. It stays installed.'=>'L’extension est désactivée. Elle reste installée.','Fine'=>'OK','Warning'=>'Avertissement','Problem'=>'Problème','Check now'=>'Vérifier maintenant','Checks'=>'Contrôles','Not checked yet. Press "Check now" to see the result.'=>'Pas encore vérifié. Cliquez sur « Vérifier maintenant » pour voir le résultat.','Alarm by e-mail'=>'Alerte par e-mail','If a new problem appears, an e-mail goes to these addresses, at most once a day for the same problem. Write one address per line. Leave it empty to switch the alarm off.'=>'En cas de nouveau problème, un e-mail est envoyé à ces adresses, pour un même problème au maximum une fois par jour. Une adresse par ligne. Laisser vide pour désactiver l’alerte.','Addresses for the alarm, one per line'=>'Adresses pour l’alerte, une par ligne','Save'=>'Enregistrer','Not checked yet'=>'Pas encore vérifié','%s. Checked automatically every morning at 06:00.'=>'%s. Vérification automatique chaque matin à 06 h 00.','Health'=>'État','Checked: there is a problem. See the list for what to do.'=>'Vérifié : un problème existe. La liste indique quoi faire.','Checked: your website is fine.'=>'Vérifié : votre site est en bon état.','Saved. The alarm is on.'=>'Enregistré. L’alerte est activée.','Saved. The alarm is off.'=>'Enregistré. L’alerte est désactivée.','The installation did not work. Please try again, or contact MomentumLab.'=>'L’installation a échoué. Veuillez réessayer ou contacter MomentumLab.','File changes are blocked on this website. Ask your host or developer to allow them.'=>'Les modifications de fichiers sont bloquées sur ce site. Demandez à votre hébergeur ou à votre développeur de les autoriser.','The plugin is already installed. Please switch it on in the list.'=>'L’extension est déjà installée. Veuillez l’activer dans la liste.','The main file is missing in the download'=>'Le fichier principal est absent du téléchargement','Overview'=>'Vue d’ensemble','Plugins'=>'Extensions','Settings'=>'Réglages','No key'=>'Aucune clé','No license yet – free plugins work without one'=>'Pas encore de licence – les extensions gratuites fonctionnent sans','Active'=>'Active','Your license is active.'=>'Votre licence est active.','Not active'=>'Inactive','Open the settings to check your license key.'=>'Ouvrez les réglages pour vérifier votre clé de licence.','License'=>'Licence','Checked today at %s'=>'Vérifié aujourd’hui à %s','Checked on %s'=>'Vérifié le %s','Website health'=>'Santé du site','The first check runs tomorrow morning.'=>'La première vérification aura lieu demain matin.','%d warning'=>'%d avertissement' . "\0" . '%d avertissements','All good'=>'Tout est bon','%1$d of %2$d fine'=>'%1$d sur %2$d en ordre','%d update'=>'%d mise à jour' . "\0" . '%d mises à jour','Up to date'=>'À jour','%d active'=>'%d active(s)','%d more unlocked'=>'%d autre(s) débloquée(s)','License problem'=>'Problème de licence','Open settings'=>'Ouvrir les réglages','View'=>'Voir','Update %s'=>'Mettre à jour %s','Version %1$s is ready. You have %2$s.'=>'La version %1$s est disponible. Vous avez la version %2$s.','Update'=>'Mettre à jour','%s is ready to install'=>'%s est prêt à être installé','Your license includes it. Switch it on to install it.'=>'Votre licence le comprend. Activez-le pour l’installer.','Install'=>'Installer','Notice'=>'Remarque','To do'=>'À faire','Nothing to do. Everything is up to date.'=>'Rien à faire. Tout est à jour.','Everything important about your website at a glance.'=>'L’essentiel de votre site en un coup d’œil.','How MomentumLab works'=>'Fonctionnement de MomentumLab','One license key covers all MomentumLab plugins on this website. Updates arrive through WordPress as usual. If the license expires, the plugins keep running – only updates and Pro features pause until you renew.'=>'Une seule clé de licence couvre toutes les extensions MomentumLab de ce site. Les mises à jour arrivent comme d’habitude via WordPress. Si la licence expire, les extensions continuent de fonctionner ; seuls les mises à jour et les fonctions Pro sont suspendues jusqu’au renouvellement.','All'=>'Tous','Available'=>'Disponibles','Filter plugins'=>'Filtrer les extensions','Installed, switched off'=>'Installées, désactivées','Not included in your license'=>'Non incluses dans votre licence','Not installed yet'=>'Pas encore installées','Switch off %s'=>'Désactiver %s','Switch on %s'=>'Activer %s','Update to %s ready'=>'Mise à jour vers %s prête','Update now'=>'Mettre à jour maintenant','No more updates: this unlock has expired. The plugin keeps running.'=>'Plus de mises à jour : cette activation a expiré. L’extension continue de fonctionner.','Renew'=>'Renouveler','On request'=>'Sur demande','Version %1$s · %2$s'=>'Version %1$s · %2$s','Ask MomentumLab'=>'Demander à MomentumLab','Reload list'=>'Recharger la liste','Switch on installs and activates. Switching off only deactivates; nothing is deleted.'=>'Activer installe et active. Désactiver se contente de désactiver ; rien n’est supprimé.','Included unlocks'=>'Activations incluses','Advanced: GitHub access'=>'Avancé : accès GitHub','Only needed if MomentumLab asks you to. With a license, updates arrive without GitHub.'=>'Nécessaire uniquement si MomentumLab vous le demande. Avec une licence, les mises à jour arrivent sans GitHub.','Usually you only enter the license key here once.'=>'En général, la clé de licence ne se saisit qu’une fois ici.','What happens when the license expires?'=>'Que se passe-t-il lorsque la licence expire ?','Your website keeps running. Updates and Pro features pause until you renew. If the MomentumLab server is briefly unreachable, everything stays as it is for 7 days.'=>'Votre site continue de fonctionner. Les mises à jour et les fonctions Pro sont suspendues jusqu’au renouvellement. Si le serveur MomentumLab est brièvement injoignable, tout reste en l’état pendant 7 jours.','For private MomentumLab repositories, WordPress needs a read token from GitHub. It is stored encrypted and never shown.'=>'Pour les dépôts privés MomentumLab, WordPress a besoin d’un jeton de lecture GitHub. Il est enregistré chiffré et n’est jamais affiché.','The token is set in wp-config.php (MLAB_GITHUB_TOKEN) and applies to all repositories.'=>'Le jeton est défini dans wp-config.php (MLAB_GITHUB_TOKEN) et s’applique à tous les dépôts.','Your website has no security keys (AUTH_KEY, SECURE_AUTH_KEY) in wp-config.php. Without them a token cannot be stored safely. Ask your host or developer to add them.'=>'Votre site ne dispose pas de clés de sécurité (AUTH_KEY, SECURE_AUTH_KEY) dans wp-config.php. Sans elles, un jeton ne peut pas être enregistré en toute sécurité. Demandez à votre hébergeur ou à votre développeur de les ajouter.','Applies to'=>'S’applique à','Token'=>'Jeton','Last test'=>'Dernier test','Actions'=>'Actions','Applies to (organization, or organization/repository)'=>'S’applique à (organisation, ou organisation/dépôt)','Token from GitHub'=>'Jeton GitHub','Save and test'=>'Enregistrer et tester','not tested yet'=>'pas encore testé','Expires on %s.'=>'Expire le %s.','Test connection'=>'Tester la connexion','Remove'=>'Supprimer','Please enter an organization (for example momentumlab-ch) or organization/repository.'=>'Veuillez saisir une organisation (par exemple momentumlab-ch) ou organisation/dépôt.','The token is set in wp-config.php and cannot be changed here.'=>'Le jeton est défini dans wp-config.php et ne peut pas être modifié ici.','This does not look like a GitHub token. A fine-grained token starts with github_pat_. Please copy it again from GitHub.'=>'Ceci ne ressemble pas à un jeton GitHub. Un jeton à permissions fines commence par github_pat_. Veuillez le copier à nouveau depuis GitHub.','The token could not be encrypted because the server has neither sodium nor openssl. Ask your host to enable one of them.'=>'Le jeton n’a pas pu être chiffré, car le serveur n’a ni sodium ni openssl. Demandez à votre hébergeur d’en activer un.','Token saved. Test: %s'=>'Jeton enregistré. Test : %s','The saved token can no longer be read because the security keys of your website have changed. Please enter the token again.'=>'Le jeton enregistré ne peut plus être lu, car les clés de sécurité du site ont changé. Veuillez le saisir à nouveau.','This token no longer exists. Reload the page.'=>'Ce jeton n’existe plus. Rechargez la page.','The token has been removed.'=>'Le jeton a été supprimé.','The MomentumLab server cannot be reached right now. Please try again in a few minutes.'=>'Le serveur MomentumLab est injoignable pour le moment. Veuillez réessayer dans quelques minutes.','GitHub is not reachable right now. Please try again later.'=>'GitHub est injoignable pour le moment. Veuillez réessayer plus tard.','Connection works.'=>'La connexion fonctionne.','GitHub rejects the token: it is wrong, expired or revoked. Please enter a new token.'=>'GitHub refuse le jeton : il est incorrect, expiré ou révoqué. Veuillez saisir un nouveau jeton.','The token has no read access. Please grant "Contents: Read" on GitHub.'=>'Le jeton n’a pas d’accès en lecture. Veuillez accorder « Contents: Read » sur GitHub.','The repository is not visible with this token. Please allow access to this repository on GitHub.'=>'Le dépôt n’est pas visible avec ce jeton. Veuillez autoriser l’accès à ce dépôt sur GitHub.','Unexpected response from GitHub (status %d).'=>'Réponse inattendue de GitHub (statut %d).','Website reachable'=>'Site accessible','The home page does not respond: %s'=>'La page d’accueil ne répond pas : %s','The home page returns error code %d.'=>'La page d’accueil renvoie l’erreur %d.','Responds in %s s.'=>'Répond en %s s.','This is slow: check caching and the server.'=>'C’est lent : vérifiez le cache et le serveur.','SSL certificate'=>'Certificat SSL','The website does not use HTTPS. Ask your host to set up an SSL certificate.'=>'Le site n’utilise pas HTTPS. Demandez à votre hébergeur d’installer un certificat SSL.','The expiry date could not be read.'=>'La date d’expiration n’a pas pu être lue.','Valid for another %1$d days (until %2$s).'=>'Valable encore %1$d jours (jusqu’au %2$s).','Does the certificate not renew by itself? Check with your host (e.g. Plesk, Let’s Encrypt).'=>'Le certificat ne se renouvelle-t-il pas automatiquement ? Vérifiez auprès de votre hébergeur (par ex. Plesk, Let’s Encrypt).','Updates'=>'Mises à jour','Everything is up to date.'=>'Tout est à jour.','%d plugin update'=>'%d mise à jour d’extension' . "\0" . '%d mises à jour d’extensions','%d theme update'=>'%d mise à jour de thème' . "\0" . '%d mises à jour de thèmes','WordPress update'=>'Mise à jour de WordPress','pending.'=>'en attente.','PHP errors'=>'Erreurs PHP','No error log is active.'=>'Aucun journal d’erreurs n’est actif.','No serious errors in the last 24 hours.'=>'Aucune erreur grave au cours des 24 dernières heures.','%d serious PHP error in the last 24 hours. Details in wp-content/debug.log.'=>'%d erreur PHP grave au cours des 24 dernières heures. Détails dans wp-content/debug.log.' . "\0" . '%d erreurs PHP graves au cours des 24 dernières heures. Détails dans wp-content/debug.log.','Backup'=>'Sauvegarde','The last backup (UpdraftPlus) was %d day ago.'=>'La dernière sauvegarde (UpdraftPlus) date d’il y a %d jour.' . "\0" . 'La dernière sauvegarde (UpdraftPlus) date d’il y a %d jours.','Please check the schedule in UpdraftPlus.'=>'Vérifiez la planification dans UpdraftPlus.','Jetpack is connected. The backup status is shown under Jetpack › VaultPress Backup.'=>'Jetpack est connecté. L’état des sauvegardes s’affiche sous Jetpack › VaultPress Backup.','Missing pages (404)'=>'Pages introuvables (404)','%d address not found in the last 24 hours.'=>'%d adresse introuvable au cours des 24 dernières heures.' . "\0" . '%d adresses introuvables au cours des 24 dernières heures.','Please check under SEO › Redirects.'=>'Vérifiez dans SEO › Redirections.','Problem on %s'=>'Problème sur %s','Overview:'=>'Vue d’ensemble :','Updates are not active: please enter a GitHub access token under MomentumLab › Settings.'=>'Les mises à jour ne sont pas actives : veuillez saisir un jeton d’accès GitHub sous MomentumLab › Réglages.','%d problem'=>'%d problème' . "\0" . '%d problèmes']];